const candidate = $('ValidateRepeatCandidate').item.json;
const orderItems = $('Get Order History').all().map(i => i.json);

// Outlook email history
const outlookItems = $('Lookup Outlook History').all().map(i => i.json);
const emailHistory = outlookItems
  .filter(e => e.subject)
  .map(e => ({
    subject: e.subject,
    preview: (e.bodyPreview || '').substring(0, 200),
    from: e.from?.emailAddress?.address || '',
    date: e.receivedDateTime || e.receivedAt || ''
  }))
  .slice(0, 8);

// PandaDoc quotes
const pandadocItems = $('Lookup PandaDoc Quotes').all().map(i => i.json);
const quotes = pandadocItems
  .filter(q => q.document_id)
  .map(q => ({
    status: q.status,
    value: q.total_value,
    created: q.created_at,
    viewed: q.viewed_at,
    signed: q.signed_at
  }));

// Extract product names from line_items
const products = orderItems.flatMap(o => {
  if (!o.line_items) return [];
  const items = Array.isArray(o.line_items) ? o.line_items : [o.line_items];
  return items.map(li => li.title || li.name || 'LED Neonschild').filter(Boolean);
});
const uniqueProducts = [...new Set(products)].slice(0, 5);

const lastOrder = new Date(candidate.last_order_date);
const monthsAgo = Math.round((Date.now() - lastOrder.getTime()) / (1000 * 60 * 60 * 24 * 30));

const isB2B = !!(candidate.company_name && candidate.company_name.trim());
const isHighValue = candidate.total_revenue >= 5000;

const greeting = candidate.first_name 
  ? candidate.first_name 
  : (isB2B ? candidate.company_name : 'Kunde');

// Build email history summary
const emailSummary = emailHistory.length > 0
  ? emailHistory.map(e => `[${e.date?.substring(0,10) || '?'}] Von: ${e.from} | Betreff: ${e.subject}`).join('\n')
  : 'Keine E-Mail-Historie gefunden';

// Build quote summary
const quoteSummary = quotes.length > 0
  ? quotes.map(q => `Status: ${q.status}, Wert: ${q.value}EUR, Erstellt: ${q.created?.substring(0,10) || '?'}${q.signed ? ', Unterschrieben: ' + q.signed.substring(0,10) : ''}`).join('\n')
  : 'Keine PandaDoc Angebote gefunden';

return [{
  json: {
    ...candidate,
    orders_summary: orderItems.map(o => ({
      number: o.shopify_order_number,
      value: o.order_value,
      date: o.shopify_created_at
    })),
    products_ordered: uniqueProducts,
    months_since_last_order: monthsAgo,
    is_b2b: isB2B,
    is_high_value: isHighValue,
    greeting_name: greeting,
    order_count: candidate.total_orders,
    total_spent: candidate.total_revenue,
    email_history: emailSummary,
    quote_history: quoteSummary,
    email_count: emailHistory.length,
    quote_count: quotes.length
  }
}];

